package me.rerere.rikkahub.data.ai.tools.local

import kotlinx.serialization.json.*
import me.rerere.ai.core.InputSchema
import me.rerere.ai.core.Tool
import me.rerere.rikkahub.utils.JsonInstantPretty
import me.rerere.ai.ui.UIMessagePart
import me.rerere.rikkahub.github.GitHubConnector

private fun result(value: JsonElement) = listOf<UIMessagePart>(UIMessagePart.Text(value.toString()))
private fun error(t: Throwable) = result(buildJsonObject { put("error", "github_request_failed"); put("detail", t.message ?: t::class.simpleName.orEmpty()) })
private fun str(o: JsonObject, key: String) = o[key]?.jsonPrimitive?.contentOrNull
private fun prop(type: String) = buildJsonObject { put("type", type) }
private fun schema(vararg required: String, properties: JsonObject) = InputSchema.Obj(properties, required.toList())
private fun basic(vararg pairs: Pair<String, String>) = buildJsonObject { pairs.forEach { put(it.first, prop(it.second)) } }
private fun read(name: String, description: String, parameters: () -> InputSchema, body: suspend (JsonObject) -> JsonElement) = Tool(name = name, description = description, parameters = parameters, execute = { runCatching { result(body(it.jsonObject)) }.getOrElse(::error) })
private fun write(name: String, description: String, properties: JsonObject, required: List<String>, body: suspend (JsonObject) -> JsonElement) = Tool(name = name, description = description, parameters = { schema(*required.toTypedArray(), properties = properties) }, needsApproval = { true }, execute = { runCatching { result(body(it.jsonObject)) }.getOrElse(::error) })

fun githubTools(connector: GitHubConnector): List<Tool> = listOf(
    Tool(name = "github_status", description = "Return GitHub connection, account, and granted scopes.", parameters = { schema(properties = buildJsonObject {}) }, execute = { result(buildJsonObject { put("connected", connector.isConnected()); connector.connectedAccount()?.let { put("account", it) }; put("scopes", JsonArray(connector.grantedScopes().map(::JsonPrimitive))) }) }),
    read("github_list_repositories", "List repositories visible to the connected account.", { schema(properties = buildJsonObject { put("page", prop("integer")) }) }) { connector.repositories(it["page"]?.jsonPrimitive?.intOrNull ?: 1).let(Json::encodeToJsonElement) },
    read("github_repository_metadata", "Read repository metadata, default branch, clone URL, language, and activity counters.", { schema("owner", "repo", properties = basic("owner" to "string", "repo" to "string")) }) { connector.repository(str(it, "owner")!!, str(it, "repo")!!).let(Json::encodeToJsonElement) },
    read("github_list_branches", "List repository branches and protection state.", { schema("owner", "repo", properties = basic("owner" to "string", "repo" to "string", "page" to "integer")) }) { connector.branches(str(it, "owner")!!, str(it, "repo")!!, it["page"]?.jsonPrimitive?.intOrNull ?: 1).let(Json::encodeToJsonElement) },
    read("github_read_file", "Read a file or directory from a repository.", { schema("owner", "repo", "path", properties = buildJsonObject { put("owner", prop("string")); put("repo", prop("string")); put("path", prop("string")); put("ref", prop("string")) }) }) { connector.contents(str(it, "owner")!!, str(it, "repo")!!, str(it, "path")!!, str(it, "ref")).let(Json::encodeToJsonElement) },
    read("github_commit_history", "Read recent commits for a repository or branch.", { schema("owner", "repo", properties = basic("owner" to "string", "repo" to "string", "branch" to "string", "page" to "integer")) }) { connector.commits(str(it, "owner")!!, str(it, "repo")!!, str(it, "branch"), it["page"]?.jsonPrimitive?.intOrNull ?: 1).let(Json::encodeToJsonElement) },
    read("github_search_code", "Search code in repositories accessible to the account.", { schema("query", properties = basic("query" to "string", "page" to "integer")) }) { connector.searchCode(str(it, "query")!!, it["page"]?.jsonPrimitive?.intOrNull ?: 1) },
    read("github_list_issues", "List repository issues, excluding pull requests.", { schema("owner", "repo", properties = basic("owner" to "string", "repo" to "string", "state" to "string", "page" to "integer")) }) { connector.issues(str(it, "owner")!!, str(it, "repo")!!, str(it, "state") ?: "open", it["page"]?.jsonPrimitive?.intOrNull ?: 1).let(Json::encodeToJsonElement) },
    read("github_list_pull_requests", "List repository pull requests.", { schema("owner", "repo", properties = basic("owner" to "string", "repo" to "string", "state" to "string", "page" to "integer")) }) { connector.pullRequests(str(it, "owner")!!, str(it, "repo")!!, str(it, "state") ?: "open", it["page"]?.jsonPrimitive?.intOrNull ?: 1).let(Json::encodeToJsonElement) },
    read("github_pull_request_reviews", "Read reviews and review states for a pull request.", { schema("owner", "repo", "number", properties = basic("owner" to "string", "repo" to "string", "number" to "integer")) }) { connector.reviews(str(it, "owner")!!, str(it, "repo")!!, it["number"]!!.jsonPrimitive.int).let(Json::encodeToJsonElement) },
    read("github_releases", "List repository releases.", { schema("owner", "repo", properties = basic("owner" to "string", "repo" to "string", "page" to "integer")) }) { connector.releases(str(it, "owner")!!, str(it, "repo")!!, it["page"]?.jsonPrimitive?.intOrNull ?: 1).let(Json::encodeToJsonElement) },
    read("github_labels_and_milestones", "Read repository labels and milestones.", { schema("owner", "repo", properties = basic("owner" to "string", "repo" to "string", "state" to "string")) }) { buildJsonObject { put("labels", JsonInstantPretty.encodeToJsonElement(connector.labels(str(it, "owner")!!, str(it, "repo")!!))); put("milestones", JsonInstantPretty.encodeToJsonElement(connector.milestones(str(it, "owner")!!, str(it, "repo")!!, str(it, "state") ?: "open"))) } },
    read("github_actions_and_checks", "Read recent GitHub Actions runs and commit checks.", { schema("owner", "repo", "ref", properties = basic("owner" to "string", "repo" to "string", "ref" to "string")) }) { buildJsonObject { put("actions", JsonInstantPretty.encodeToJsonElement(connector.actionRuns(str(it, "owner")!!, str(it, "repo")!!))); put("checks", JsonInstantPretty.encodeToJsonElement(connector.checkRuns(str(it, "owner")!!, str(it, "repo")!!, str(it, "ref")!!))) } },
    write("github_create_branch", "Create a branch. Remote mutations require approval.", basic("owner" to "string", "repo" to "string", "branch" to "string", "from_sha" to "string"), listOf("owner", "repo", "branch", "from_sha")) { connector.createBranch(str(it, "owner")!!, str(it, "repo")!!, str(it, "branch")!!, str(it, "from_sha")!!); buildJsonObject { put("ok", true) } },
    write("github_write_file", "Create or update a repository file and commit it to a branch. Requires approval.", buildJsonObject { put("owner", prop("string")); put("repo", prop("string")); put("path", prop("string")); put("message", prop("string")); put("content_base64", prop("string")); put("branch", prop("string")); put("sha", prop("string")) }, listOf("owner", "repo", "path", "message", "content_base64", "branch")) { connector.createOrUpdateFile(str(it, "owner")!!, str(it, "repo")!!, str(it, "path")!!, str(it, "message")!!, str(it, "content_base64")!!, str(it, "branch")!!, str(it, "sha")).also { } },
    write("github_create_issue", "Create an issue with optional labels and milestone. Requires approval.", buildJsonObject { put("owner", prop("string")); put("repo", prop("string")); put("title", prop("string")); put("body", prop("string")); put("labels", buildJsonObject { put("type", "array"); put("items", prop("string")) }); put("milestone", prop("integer")) }, listOf("owner", "repo", "title")) { connector.createIssue(str(it, "owner")!!, str(it, "repo")!!, str(it, "title")!!, str(it, "body"), it["labels"]?.jsonArray?.map { p -> p.jsonPrimitive.content } ?: emptyList(), it["milestone"]?.jsonPrimitive?.intOrNull) },
    write("github_create_pull_request", "Create a pull request. Requires approval.", buildJsonObject { put("owner", prop("string")); put("repo", prop("string")); put("title", prop("string")); put("head", prop("string")); put("base", prop("string")); put("body", prop("string")) }, listOf("owner", "repo", "title", "head", "base")) { connector.createPullRequest(str(it, "owner")!!, str(it, "repo")!!, str(it, "title")!!, str(it, "head")!!, str(it, "base")!!, str(it, "body")) },
    write("github_review_pull_request", "Submit an approve, request-changes, or comment review. Requires approval.", buildJsonObject { put("owner", prop("string")); put("repo", prop("string")); put("number", prop("integer")); put("event", prop("string")); put("body", prop("string")) }, listOf("owner", "repo", "number", "event")) { connector.reviewPullRequest(str(it, "owner")!!, str(it, "repo")!!, it["number"]!!.jsonPrimitive.int, str(it, "event")!!, str(it, "body")) },
    write("github_create_release", "Create a release. This is a high-impact mutation and requires approval.", buildJsonObject { put("owner", prop("string")); put("repo", prop("string")); put("tag", prop("string")); put("name", prop("string")); put("body", prop("string")); put("draft", prop("boolean")); put("prerelease", prop("boolean")) }, listOf("owner", "repo", "tag")) { connector.createRelease(str(it, "owner")!!, str(it, "repo")!!, str(it, "tag")!!, str(it, "name"), str(it, "body"), it["draft"]?.jsonPrimitive?.booleanOrNull ?: false, it["prerelease"]?.jsonPrimitive?.booleanOrNull ?: false) },
)
